185: /**
186:  * Decrypts AES-256-GCM gateway response using Node.js crypto.
187:  * 
188:  * @param {Buffer} respBuf - Raw response from api.wing.st/g
189:  * @param {Buffer} responseKey - 32-byte AES key
190:  * @param {number} keyId - Key version byte
191:  * @param {Buffer} ephemeralPublic - 65-byte public key
192:  * @returns {object} Decoded JSON response
193:  */
194: function decryptResponse(respBuf, responseKey, keyId, ephemeralPublic) {
195:   if (respBuf.length < GCM_IV_LEN + GCM_TAG_LEN) {
196:     throw new Error('Gateway response buffer too short: ' + respBuf.length + ' bytes (minimum 28 required)');
197:   }
198: 
199:   const iv = respBuf.subarray(0, GCM_IV_LEN);
200:   const authTag = respBuf.subarray(respBuf.length - GCM_TAG_LEN);
201:   const ciphertext = respBuf.subarray(GCM_IV_LEN, respBuf.length - GCM_TAG_LEN);
202: 
203:   const aad = Buffer.concat([
204:     Buffer.from(PROTOCOL_ID, 'utf8'),
205:     Buffer.from([0, 2, keyId]),
206:     ephemeralPublic
207:   ]);
208: 
209:   const decipher = crypto.createDecipheriv('aes-256-gcm', responseKey, iv);
210:   decipher.setAAD(aad);
211:   decipher.setAuthTag(authTag);
212: 
213:   const decrypted = Buffer.concat([
214:     decipher.update(ciphertext),
215:     decipher.final()
216:   ]);
217: 
218:   return JSON.parse(decrypted.toString('utf8'));
219: }
